172→static struct nxplayer_s *s_play;
173→
174→static struct nxplayer_s *player_get(void)
175→{
176→  if (!s_play)
177→    {
178→      s_play = nxplayer_create();
179→      if (s_play)
180→        {
181→          (void)nxplayer_setdevice(s_play, "/dev/audio/pcm0p");
