284→static void json_escape(const char *in, char *out, size_t cap)
285→{
286→  size_t o = 0;
287→  size_t i;
288→  if (!in || !out || cap < 2)
289→    {
290→      if (out && cap)
291→        {
292→          out[0] = '\0';
293→        }
294→      return;
295→    }
296→  for (i = 0; in[i] && o + 8 < cap; i++)
297→    {
298→      unsigned char ch = (unsigned char)in[i];
299→      if (ch == '"' || ch == '\\')
300→        {
301→          out[o++] = '\\';
302→          out[o++] = (char)ch;
303→        }
304→      else if (ch == '\n')
305→        {
306→          out[o++] = '\\';
307→          out[o++] = 'n';
308→        }
309→      else if (ch >= 0x20)
310→        {
311→          out[o++] = (char)ch;
312→        }
313→    }
314→  out[o] = '\0';
315→}
