317→/* nsh system() strips quotes — run curl from a script file */
318→static int run_curl_script(const char *line)
319→{
320→  FILE *f = fopen("/tmp/dm_curl.sh", "w");
321→  int rc;
322→  if (!f)
323→    {
324→      return -1;
325→    }
326→  fputs("#!/bin/sh\n", f);
327→  fputs(line, f);
328→  fputs("\n", f);
329→  fclose(f);
330→  rc = system("sh /tmp/dm_curl.sh");
331→  return rc == 0 ? 0 : -1;
332→}
