729→int dm_voice_asr_chat_tts(const char *wav_path, char *reply, int cap)
730→{
731→  char text[256];
732→
733→  if (!wav_path || !reply || cap < 8)
734→    {
735→      return -1;
736→    }
737→  reply[0] = '\0';
738→
739→  s_st = DM_VOICE_ASR;
740→  if (asr_wav(wav_path, text, sizeof(text)) != 0)
741→    {
742→      s_st = DM_VOICE_ERR;
743→      return -1;
744→    }
745→
746→  s_st = DM_VOICE_CHAT;
747→  if (chat_reply(text, reply, cap) != 0)
748→    {
749→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
750→      reply[cap - 1] = '\0';
751→      s_st = DM_VOICE_ERR;
752→      return -1;
753→    }
754→
755→  /* show text first, then speak on 4R 3W speaker */
756→  s_st = DM_VOICE_TTS;
757→  if (tts_synth(reply, WAV_TTS) == 0)
758→    {
759→      s_st = DM_VOICE_PLAY;
760→      play_wav(WAV_TTS);
761→    }
762→  s_st = DM_VOICE_IDLE;
763→  return 0;
764→}
