 562→
 563→/* Parse /tmp/wifi_scan_result.txt:
 564→ *   bssid / frequency / signal level / encode / ssid
 565→ *   74:39:89:f8:f0:ae       5240    -59     0803    Programmers7
 566→ *   d2:ad:08:f8:eb:71       2462    -88     0803    DIRECT-71-HP Smart Tank 750
 567→ *
 568→ * Preserves spaces inside SSIDs, skips hidden (empty) SSIDs and non-MAC lines,
 569→ * deduplicates same-SSID entries (keeping strongest RSSI), and sorts by RSSI.
 570→ */
 571→static int collect_aps_from_txt(void)
 572→{
 573→  FILE *fp;
 574→  char line[256];
 575→  int n = 0;
 576→  int i;
 577→  int j;
 578→
 579→  fp = fopen("/tmp/wifi_scan_result.txt", "r");
 580→  if (!fp)
 581→    {
 582→      return -1;
 583→    }
 584→
 585→  pthread_mutex_lock(&s_lock);
 586→  s_ap_n = 0;
 587→
 588→  while (fgets(line, sizeof(line), fp) && n < DM_WIFI_AP_MAX)
 589→    {
 590→      char *p = line;
 591→      char *tok_bssid;
 592→      char *tok_freq;
 593→      char *tok_rssi;
 594→      char *tok_enc;
 595→      char *ssid_start;
 596→      size_t ssid_len;
 597→      int rssi;
 598→      bool is_open;
 599→      int dup_idx = -1;
 600→
 601→      line[strcspn(line, "\r\n")] = 0;
 602→
 603→      while (*p == ' ' || *p == '\t')
 604→        {
 605→          p++;
 606→        }
 607→      if (!*p || strncmp(p, "bssid", 5) == 0)
 608→        {
 609→          continue;
 610→        }
 611→
 612→      /* Field 0: BSSID (must contain ':') */
 613→      tok_bssid = p;
 614→      while (*p && *p != ' ' && *p != '\t')
 615→        {
 616→          p++;
 617→        }
 618→      if (!*p)
 619→        {
 620→          continue;
 621→        }
 622→      *p++ = 0;
 623→      if (strchr(tok_bssid, ':') == NULL)
 624→        {
 625→          continue;
 626→        }
 627→
 628→      /* Field 1: frequency */
 629→      while (*p == ' ' || *p == '\t')
 630→        {
 631→          p++;
 632→        }
 633→      tok_freq = p;
 634→      while (*p && *p != ' ' && *p != '\t')
 635→        {
 636→          p++;
 637→        }
 638→      if (!*p || !*tok_freq)
 639→        {
 640→          continue;
 641→        }
 642→      *p++ = 0;
 643→
 644→      /* Field 2: signal level (RSSI) */
 645→      while (*p == ' ' || *p == '\t')
 646→        {
 647→          p++;
 648→        }
 649→      tok_rssi = p;
 650→      while (*p && *p != ' ' && *p != '\t')
 651→        {
 652→          p++;
 653→        }
 654→      if (!*p || !*tok_rssi)
 655→        {
 656→          continue;
 657→        }
 658→      *p++ = 0;
 659→      rssi = atoi(tok_rssi);
 660→
 661→      /* Field 3: encode (0000 = open, otherwise encrypted) */
 662→      while (*p == ' ' || *p == '\t')
 663→        {
 664→          p++;
 665→        }
 666→      tok_enc = p;
 667→      while (*p && *p != ' ' && *p != '\t')
 668→        {
 669→          p++;
 670→        }
 671→      if (*p)
 672→        {
 673→          *p++ = 0;
 674→        }
 675→      if (!*tok_enc)
 676→        {
 677→          continue;
 678→        }
 679→      is_open = (strcmp(tok_enc, "0000") == 0);
 680→
 681→      /* Field 4+: entire remainder of line is SSID (may contain spaces) */
 682→      while (*p == ' ' || *p == '\t')
 683→        {
 684→          p++;
 685→        }
 686→      ssid_start = p;
 687→      ssid_len = strlen(ssid_start);
 688→      while (ssid_len > 0 &&
 689→             (ssid_start[ssid_len - 1] == ' ' ||
 690→              ssid_start[ssid_len - 1] == '\t'))
 691→        {
 692→          ssid_start[--ssid_len] = 0;
 693→        }
 694→      if (ssid_len == 0)
 695→        {
 696→          /* Hidden AP with blank SSID */
 697→          continue;
 698→        }
 699→
 700→      /* Deduplicate by SSID: keep strongest RSSI */
 701→      for (i = 0; i < n; i++)
 702→        {
 703→          if (strncmp(s_aps[i].ssid, ssid_start, sizeof(s_aps[i].ssid) - 1) == 0)
 704→            {
 705→              dup_idx = i;
 706→              break;
 707→            }
 708→        }
 709→      if (dup_idx >= 0)
 710→        {
 711→          if (rssi > s_aps[dup_idx].rssi)
 712→            {
 713→              s_aps[dup_idx].rssi = rssi;
 714→              s_aps[dup_idx].open = is_open;
 715→            }
 716→          continue;
 717→        }
 718→
 719→      strncpy(s_aps[n].ssid, ssid_start, sizeof(s_aps[n].ssid) - 1);
 720→      s_aps[n].ssid[sizeof(s_aps[n].ssid) - 1] = 0;
 721→      s_aps[n].rssi = rssi;
 722→      s_aps[n].open = is_open;
 723→      n++;
 724→    }
 725→
 726→  /* Sort APs by RSSI descending (strongest signal first) */
 727→  for (i = 0; i < n - 1; i++)
 728→    {
 729→      for (j = i + 1; j < n; j++)
 730→        {
 731→          if (s_aps[j].rssi > s_aps[i].rssi)
 732→            {
 733→              dm_ap_t tmp = s_aps[i];
 734→              s_aps[i] = s_aps[j];
 735→              s_aps[j] = tmp;
 736→            }
 737→        }
 738→    }
 739→
 740→  s_ap_n = n;
 741→  if (s_sel >= s_ap_n)
 742→    {
 743→      s_sel = (s_ap_n > 0) ? 0 : -1;
 744→    }
 745→  pthread_mutex_unlock(&s_lock);
 746→  fclose(fp);
 747→  return n;
 748→}
