 750→static void *scan_thread(void *arg)
 751→{
 752→  int i;
 753→  int n;
 754→
 755→  (void)arg;
 756→
 757→  if (!s_wifi_enabled)
 758→    {
 759→      s_scan_busy = 0;
 760→      s_scan_ready = 1;
 761→      return NULL;
 762→    }
 763→
 764→  /* Wait briefly if an auto-connect thread is yielding */
 765→  for (i = 0; i < 50 && s_conn_busy; i++)
 766→    {
 767→      usleep(100 * 1000);
 768→    }
 769→
 770→  if (ensure_driver() < 0)
 771→    {
 772→      s_scan_busy = 0;
 773→      s_scan_ready = 1;
 774→      return NULL;
 775→    }
 776→
 777→  /* Only bring interface up in STA mode if not already connected */
 778→  if (!dm_wifi_connected())
 779→    {
 780→      cli_sta_up();
 781→      usleep(200 * 1000);
 782→    }
 783→
 784→  /* Match 9.5 demo get_wifi.sh: wapi scan wlan0 > /tmp/wifi_scan_result.txt */
 785→  (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
 786→  usleep(300 * 1000);
 787→
 788→  n = collect_aps_from_txt();
 789→  if (n <= 0)
 790→    {
 791→      usleep(500 * 1000);
 792→      (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
 793→      usleep(300 * 1000);
 794→      n = collect_aps_from_txt();
 795→    }
 796→
 797→  syslog(LOG_INFO, "[deskmate-wifi] wapi scan -> %d aps\n", n);
 798→  for (i = 0; i < s_ap_n; i++)
 799→    {
 800→      syslog(LOG_INFO, "[deskmate-wifi]  ap %s rssi=%d open=%d\n",
 801→             s_aps[i].ssid, s_aps[i].rssi, (int)s_aps[i].open);
 802→    }
 803→
 804→  s_scan_busy = 0;
 805→  s_scan_ready = 1;
 806→  return NULL;
 807→}
