 809→int dm_wifi_start_scan(void)
 810→{
 811→  pthread_t th;
 812→  pthread_attr_t attr;
 813→  int ret;
 814→
 815→  if (!s_wifi_enabled)
 816→    {
 817→      return -1;
 818→    }
 819→
 820→  if (s_scan_busy)
 821→    {
 822→      return 0;
 823→    }
 824→
 825→  /* Interrupt any background boot auto-connect so manual scan is never blocked */
 826→  s_manual_override = 1;
 827→  if (s_conn_busy && !s_conn_is_auto)
 828→    {
 829→      return -1;
 830→    }
 831→
 832→  s_scan_ready = 0;
 833→  s_scan_busy = 1;
 834→  pthread_attr_init(&attr);
 835→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
 836→  ret = pthread_create(&th, &attr, scan_thread, NULL);
 837→  pthread_attr_destroy(&attr);
 838→  if (ret != 0)
 839→    {
 840→      s_scan_busy = 0;
 841→      return -1;
 842→    }
 843→  pthread_detach(th);
 844→  return 0;
 845→}
