146→static void kick_job(int job)
147→{
148→  pthread_t th;
149→  pthread_attr_t attr;
150→
151→  if (s_busy)
152→    {
153→      return;
154→    }
155→  s_busy = true;
156→  s_job = job;
157→  s_ui_rec = false;
158→  s_rec_sec = 0;
159→  s_out_ready = 0;
160→  s_out_ans[0] = '\0';
161→  s_out_sub[0] = '\0';
162→
163→  dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
164→  set_ans(job == 1 ? dm_t("识别中…", "Recognizing…")
165→                   : dm_t("思考中…", "Thinking…"));
166→  set_ptt("处理中…", "Working…", C_BTN_HI);
167→
168→  pthread_attr_init(&attr);
169→  pthread_attr_setstacksize(&attr, 24576);
170→  if (pthread_create(&th, &attr, voice_worker, NULL) == 0)
171→    {
172→      pthread_detach(th);
173→    }
174→  else
175→    {
176→      s_busy = false;
177→      set_ptt("开始说话", "Start talk", C_BTN);
178→    }
179→  pthread_attr_destroy(&attr);
180→}
