314→        }
315→      dm_face_set(FACE_HAPPY, EYE_DECOR_NONE, 8);
316→      reset_to_idle();
317→    }
318→
319→  if (s_ui_rec && !s_busy)
320→    {
321→      char buf[80];
322→      s_rec_sec++;
323→      if (dm_voice_rec_active())
324→        {
325→          snprintf(buf, sizeof(buf),
326→                   dm_t("● 录音中 %d 秒 · 再点一下结束并发送",
327→                        "● Recording %ds · tap again to send"),
328→                   s_rec_sec);
329→          set_ans(buf);
330→          set_sub((s_rec_sec & 1) ? dm_t("正在听…", "Listening…")
331→                                  : dm_t("对准麦克风说话", "Speak to the mic"));
332→        }
333→      else
334→        {
