 51→
 52→int curl4nx_easy_setopt(FAR struct curl4nx_s *handle, int option,
 53→                        FAR void *param)
 54→{
 55→  int ret;
 56→  int cret = CURL4NXE_OK;
 57→  char scheme[16];
 58→
 59→  switch (option)
 60→    {
 61→      case CURL4NXOPT_URL:
 62→        {
 63→          struct url_s url;
 64→          memset(&url, 0, sizeof(struct url_s));
 65→          url.scheme = scheme;
 66→          url.schemelen = sizeof(scheme);
 67→          url.host = handle->host;
 68→          url.hostlen = CONFIG_LIBCURL4NX_MAXHOST;
 69→          url.path = handle->path;
 70→          url.pathlen = CONFIG_LIBCURL4NX_MAXPATH;
 71→
 72→          ret = netlib_parseurl(param, &url);
 73→
 74→          if (ret == -E2BIG)
 75→            {
 76→              cret = CURL4NXE_OUT_OF_MEMORY;
 77→              break;
 78→            }
 79→          else if (ret != 0) /* includes -EINVAL */
 80→            {
 81→              curl4nx_warn("Malformed URL: %s\n", param);
 82→              cret = CURL4NXE_URL_MALFORMAT;
 83→              break;
 84→            }
 85→
 86→          if (url.port == 0)
 87→            {
 88→              curl4nx_err("Invalid port 0\n");
 89→              cret = CURL4NXE_URL_MALFORMAT; /* User passed invalid port */
 90→              break;
 91→            }
 92→
 93→          if (url.host[0] == 0)
 94→            {
 95→              curl4nx_err("Empty host\n");
 96→              cret = CURL4NXE_URL_MALFORMAT; /* User passed empty host */
 97→              break;
 98→            }
 99→
100→          if (strncmp(scheme, "http", strlen(scheme)))
101→            {
102→              curl4nx_err("Unsupported protocol '%s'\n", scheme);
103→              cret = CURL4NXE_UNSUPPORTED_PROTOCOL;
104→              break;
105→            }
106→
107→          handle->port = url.port;
108→          curl4nx_info("found scheme: %s\n", scheme);
109→          curl4nx_info("found host  : %s\n", handle->host);
110→          curl4nx_info("found port  : %d\n", handle->port);
111→          curl4nx_info("found path  : %s\n", handle->path);
112→          break;
113→        }
114→
115→      case CURL4NXOPT_PORT:
116→        {
117→          long port = (long)param;
118→          if (port == 0)
119→            {
120→              cret = CURL4NXE_BAD_FUNCTION_ARGUMENT;
121→              break;
122→            }
123→
124→          handle->port = (uint16_t)(port & 0xffff);
125→          break;
126→        }
127→
128→      case CURL4NXOPT_BUFFERSIZE:
129→        {
130→          long len = (long)param;
131→          if (len < CONFIG_LIBCURL4NX_MINRXBUFLEN ||
132→             len > CONFIG_LIBCURL4NX_MAXRXBUFLEN)
133→            {
134→              cret = CURL4NXE_BAD_FUNCTION_ARGUMENT;
135→              break;
136→            }
137→
138→          if (handle->rxbuf)
139→            {
140→              curl4nx_info("Freeing previous buffer\n");
141→              free(handle->rxbuf);
142→            }
143→
144→          handle->rxbuf = malloc(len);
145→          if (!handle->rxbuf)
146→            {
147→              cret = CURL4NXE_OUT_OF_MEMORY;
148→              break;
149→            }
150→
151→          handle->rxbufsize = len;
152→          break;
153→        }
154→
155→      case CURL4NXOPT_HEADERFUNCTION:
156→        if (param == NULL)
157→          {
158→            cret = CURL4NXE_BAD_FUNCTION_ARGUMENT;
159→            break;
160→          }
161→
162→        handle->headerfunc = param;
163→        break;
164→
165→      case CURL4NXOPT_HEADERDATA:
166→        handle->headerdata = param;
167→        break;
168→
169→      case CURL4NXOPT_FAILONERROR:
170→        if ((long)param)
171→          {
172→            handle->flags |= CURL4NX_FLAGS_FAILONERROR;
173→          }
174→        else
175→          {
176→            handle->flags &= ~CURL4NX_FLAGS_FAILONERROR;
177→          }
178→        break;
179→
180→      case CURL4NXOPT_FOLLOWLOCATION:
181→        if ((long)param)
182→          {
183→            handle->flags |= CURL4NX_FLAGS_FOLLOWLOCATION;
184→          }
185→        else
186→          {
187→            handle->flags &= ~CURL4NX_FLAGS_FOLLOWLOCATION;
188→          }
189→        break;
190→
191→      case CURL4NXOPT_MAXREDIRS:
192→        {
193→          long redirs = (long)param;
194→          if (redirs < -1 ||
195→             redirs > CONFIG_LIBCURL4NX_MAXREDIRS)
196→            {
197→              cret = CURL4NXE_BAD_FUNCTION_ARGUMENT;
198→              break;
199→            }
200→
201→          handle->max_redirs = redirs;
202→          break;
203→        }
204→
205→      case CURL4NXOPT_VERBOSE:
206→        if ((long)param)
207→          {
208→            handle->flags |= CURL4NX_FLAGS_VERBOSE;
209→          }
210→        else
211→          {
212→            handle->flags &= ~CURL4NX_FLAGS_VERBOSE;
213→          }
214→        break;
215→
216→      default:
217→        cret = CURL4NXE_UNKNOWN_OPTION;
218→        break;
219→    }
220→
221→  return cret;
222→}
