 88→static void *rec_auto_stop(void *arg)
 89→{
 90→  int max_sec = (int)(intptr_t)arg;
 91→
 92→  sleep(max_sec > 0 ? max_sec : REC_MAX_SEC);
 93→  (void)dm_voice_rec_stop();
