371→static const char b64tab[] =
372→    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
373→
374→static int b64_encode(const unsigned char *in, size_t inlen, char *out, size_t outcap)
375→{
376→  size_t i = 0, o = 0;
377→  while (i < inlen && o + 4 < outcap)
378→    {
379→      unsigned int v = in[i++] << 16;
380→      if (i < inlen) v |= in[i++] << 8;
381→      if (i < inlen) v |= in[i++];
382→      out[o++] = b64tab[(v >> 18) & 63];
383→      out[o++] = b64tab[(v >> 12) & 63];
384→      out[o++] = b64tab[(v >> 6) & 63];
385→      out[o++] = b64tab[v & 63];
386→    }
387→  out[o] = '\0';
388→  return (int)o;
389→}
390→
391→static int b64_decode(const char *in, unsigned char *out, size_t outcap)
392→{
393→  int val = 0, valb = -8;
394→  size_t o = 0;
395→  for (; *in && *in != '=' && o < outcap; in++)
396→    {
397→      const char *p = strchr(b64tab, *in);
398→      if (!p) continue;
399→      val = (val << 6) + (int)(p - b64tab);
400→      valb += 6;
401→      if (valb >= 0)
402→        {
403→          out[o++] = (unsigned char)((val >> valb) & 255);
404→          valb -= 8;
405→        }
406→    }
407→  return (int)o;
408→}
