 97→int dm_voice_rec_start(int max_seconds)
 98→{
 99→  pthread_t th;
100→  pthread_attr_t attr;
101→
102→  pthread_mutex_lock(&s_rec_lock);
103→  if (s_rec_active)
104→    {
105→      pthread_mutex_unlock(&s_rec_lock);
106→      return 0;
107→    }
108→
109→  unlink(WAV_REC);
110→  s_rec = nxrecorder_create();
111→  if (!s_rec)
112→    {
113→      pthread_mutex_unlock(&s_rec_lock);
114→      s_st = DM_VOICE_ERR;
115→      return -1;
116→    }
117→  (void)nxrecorder_setdevice(s_rec, "/dev/audio/pcm0c");
118→  if (nxrecorder_recordinternal(s_rec, WAV_REC, AUDIO_FMT_PCM,
119→                                REC_CH, REC_BITS, REC_RATE, 1) != OK)
120→    {
121→      nxrecorder_release(s_rec);
122→      s_rec = NULL;
123→      pthread_mutex_unlock(&s_rec_lock);
124→      s_st = DM_VOICE_ERR;
125→      return -1;
126→    }
127→  s_rec_active = 1;
128→  s_st = DM_VOICE_REC;
129→  pthread_mutex_unlock(&s_rec_lock);
130→
131→  pthread_attr_init(&attr);
132→  pthread_attr_setstacksize(&attr, 4096);
133→  if (pthread_create(&th, &attr, rec_auto_stop,
134→                     (void *)(intptr_t)(max_seconds > 0 ? max_seconds
135→                                                        : REC_MAX_SEC)) == 0)
136→    {
137→      pthread_detach(th);
138→    }
139→  pthread_attr_destroy(&attr);
140→  return 0;
141→}
142→
143→int dm_voice_rec_stop(void)
144→{
145→  FILE *f;
146→  long size;
147→
148→  pthread_mutex_lock(&s_rec_lock);
149→  if (s_rec_active)
150→    {
151→      s_rec_active = 0;
152→      if (s_rec)
153→        {
154→          nxrecorder_stop(s_rec);
155→          nxrecorder_release(s_rec);
156→          s_rec = NULL;
157→        }
158→      s_st = DM_VOICE_IDLE;
159→    }
160→  pthread_mutex_unlock(&s_rec_lock);
161→
162→  f = fopen(WAV_REC, "rb");
163→  if (!f)
164→    {
165→      syslog(LOG_ERR, "[dm-voice] recording file missing\n");
166→      s_st = DM_VOICE_ERR;
167→      return -1;
168→    }
169→
170→  if (fseek(f, 0, SEEK_END) != 0)
171→    {
172→      fclose(f);
173→      s_st = DM_VOICE_ERR;
174→      return -1;
175→    }
176→
177→  size = ftell(f);
178→  fclose(f);
179→  if (size <= 44)
180→    {
181→      syslog(LOG_ERR, "[dm-voice] recording has no audio payload\n");
182→      s_st = DM_VOICE_ERR;
183→      return -1;
184→    }
185→
186→  return 0;
187→}
