338→/* Run curl from a script so nsh cannot strip quoted header arguments. */
339→static int run_curl_script(const char *line)
340→{
341→  FILE *f = fopen(VOICE_CURL_SCRIPT, "w");
342→  int write_ok;
343→  int close_rc;
344→  int rc;
345→
346→  if (!f)
347→    {
348→      syslog(LOG_ERR, "[dm-voice] cannot create curl script\n");
349→      return -1;
350→    }
351→
352→  write_ok = fputs("#!/bin/sh\n", f) != EOF &&
353→             fputs(line, f) != EOF && fputc('\n', f) != EOF;
354→  close_rc = fclose(f);
355→  if (!write_ok || close_rc != 0)
356→    {
357→      syslog(LOG_ERR, "[dm-voice] cannot write curl script\n");
358→      return -1;
359→    }
360→
361→  rc = system("sh " VOICE_CURL_SCRIPT);
362→  if (rc != 0)
363→    {
364→      syslog(LOG_ERR, "[dm-voice] curl script failed status=%d\n", rc);
365→      return -1;
366→    }
367→  return 0;
368→}
