169→static void kick_job(int job)
170→{
171→  pthread_t th;
172→  pthread_attr_t attr;
173→
174→  if (s_busy)
175→    {
176→      return;
177→    }
178→  s_busy = true;
179→  s_job = job;
180→  s_ui_rec = false;
181→  s_rec_sec = 0;
182→  s_out_ready = 0;
183→  s_out_ans[0] = '\0';
184→  s_out_sub[0] = '\0';
185→
186→  dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
187→  set_ans(job == 1 ? dm_t("识别中…", "Recognizing…")
188→                   : dm_t("思考中…", "Thinking…"));
189→  set_ptt("处理中…", "Working…", C_BTN_HI);
190→
191→  pthread_attr_init(&attr);
192→  pthread_attr_setstacksize(&attr, 24576);
193→  if (pthread_create(&th, &attr, voice_worker, NULL) == 0)
194→    {
195→      pthread_detach(th);
196→    }
197→  else
198→    {
199→      s_busy = false;
200→      set_ptt("开始说话", "Start talk", C_BTN);
201→    }
202→  pthread_attr_destroy(&attr);
203→}
