1210→  /* Release our audio buffers and unregister / release the device */
1211→
1212→err_out:
1213→  audinfo("Clean-up and exit\n");
1214→
1215→  if (buffers != NULL)
1216→    {
1217→      audinfo("Freeing buffers\n");
1218→      for (x = 0; x < buf_info.nbuffers; x++)
1219→        {
1220→          /* Fill in the buffer descriptor struct to issue a free request */
1221→
1222→          if (buffers[x] != NULL)
1223→            {
1224→#ifdef CONFIG_AUDIO_MULTI_SESSION
1225→              buf_desc.session = pplayer->session;
1226→#endif
1227→              buf_desc.u.buffer = buffers[x];
1228→              ioctl(pplayer->dev_fd, AUDIOIOC_FREEBUFFER,
1229→                    (unsigned long)&buf_desc);
1230→            }
1231→        }
1232→
1233→      /* Free the pointers to the buffers */
1234→
1235→      free(buffers);
1236→    }
1237→
1238→  /* Unregister the message queue and release the session */
1239→
1240→  ioctl(pplayer->dev_fd, AUDIOIOC_UNREGISTERMQ, (unsigned long)pplayer->mq);
1241→
1242→#ifdef CONFIG_AUDIO_MULTI_SESSION
1243→  ioctl(pplayer->dev_fd, AUDIOIOC_RELEASE, (unsigned long)pplayer->session);
1244→#else
1245→  ioctl(pplayer->dev_fd, AUDIOIOC_RELEASE, 0);
1246→#endif
1247→
1248→  /* Cleanup */
1249→
1250→  pthread_mutex_lock(&pplayer->mutex);
1251→
1252→  /* Close the files */
1253→
1254→  if (0 < pplayer->fd)
1255→    {
1256→      close(pplayer->fd);                 /* Close the file */
1257→      pplayer->fd = -1;                   /* Clear out the FD */
1258→    }
1259→
1260→  close(pplayer->dev_fd);                 /* Close the device */
1261→  pplayer->dev_fd = -1;                   /* Mark device as closed */
1262→  DEBUGVERIFY(mq_close(pplayer->mq));     /* Close the message queue */
1263→  mq_unlink(pplayer->mqname);             /* Unlink the message queue */
1264→  pplayer->ops   = NULL;                  /* Clear offload parser */
1265→  pplayer->state = NXPLAYER_STATE_IDLE;   /* Go to IDLE */
1266→
1267→  /* Clear the tone field */
1268→
1269→  memset(&pplayer->tone, 0, sizeof(pplayer->tone));
1270→
1271→  pthread_mutex_unlock(&pplayer->mutex);
1272→
1273→  /* The playthread is done with the context.  Release it, which may
1274→   * actually cause the context to be freed if the creator has already
1275→   * abandoned (released) the context too.
1276→   */
1277→
1278→  nxplayer_release(pplayer);
1279→
1280→  audinfo("Exit\n");
1281→
1282→  return NULL;
1283→}
