1807→int nxplayer_stop(FAR struct nxplayer_s *pplayer)
1808→{
1809→  struct audio_msg_s term_msg;
1810→
1811→  DEBUGASSERT(pplayer != NULL);
1812→
1813→  /* Validate we are not in IDLE state */
1814→
1815→  pthread_mutex_lock(&pplayer->mutex);
1816→  if (pplayer->state == NXPLAYER_STATE_IDLE)
1817→    {
