1334→/****************************************************************************
1335→ * Name: nxrecorder_release
1336→ *
1337→ *   nxrecorder_release() reduces the reference count by one and if it
1338→ *   reaches zero, frees the context.
1339→ *
1340→ * Input Parameters:
1341→ *   precorder    Pointer to the NxRecorder context
1342→ *
1343→ * Returned values:    None
1344→ *
1345→ ****************************************************************************/
1346→
1347→void nxrecorder_release(FAR struct nxrecorder_s *precorder)
1348→{
1349→  int         refcount;
1350→
1351→  /* Check if there was a previous thread and join it if there was */
1352→
1353→  nxrecorder_jointhread(precorder);
1354→
1355→  pthread_mutex_lock(&precorder->mutex);
1356→
1357→  /* Reduce the reference count */
1358→
1359→  refcount = precorder->crefs--;
1360→  pthread_mutex_unlock(&precorder->mutex);
1361→
1362→  /* If the ref count *was* one, then free the context */
1363→
1364→  if (refcount == 1)
1365→    {
1366→      pthread_mutex_destroy(&precorder->mutex);
1367→      free(precorder);
1368→    }
1369→}
