 65→static int med_due_count(void)
 66→{
 67→  FILE *f = fopen("/data/deskmate_med.txt", "r");
 68→  char line[160];
 69→  int due = 0;
 70→  time_t now = time(NULL);
 71→  struct tm tmv;
 72→  int hour;
 73→
 74→  if (!f)
 75→    {
 76→      return 0;
 77→    }
 78→  localtime_r(&now, &tmv);
 79→  hour = tmv.tm_hour;
 80→
 81→  while (fgets(line, sizeof(line), f))
 82→    {
 83→      char name[32];
 84→      int times = 0;
 85→      int h0 = 0, h1 = 0, h2 = 0;
 86→      int taken = 0, day = 0;
 87→      if (sscanf(line, "%31[^|]|%d|%d,%d,%d|%d|%d",
 88→                 name, &times, &h0, &h1, &h2, &taken, &day) == 7)
 89→        {
 90→          int today = (int)(now / 86400);
 91→          int hs[3] = { h0, h1, h2 };
 92→          int k;
 93→
 94→          if (day != today)
 95→            {
 96→              taken = 0;
 97→            }
 98→          for (k = 0; k < times && k < 3; k++)
 99→            {
100→              if (!(taken & (1u << k)) && hour >= hs[k] && hour < hs[k] + 2)
101→                {
102→                  due++;
103→                  break;
104→                }
105→            }
106→        }
107→    }
108→  fclose(f);
109→  return due;
110→}
111→
112→static int water_due(void)
113→{
114→  FILE *f = fopen("/data/deskmate_water.txt", "r");
115→  int cups = 0, iv = 30;
116→  long due = 0;
117→  int goal = 8;
118→
119→  if (!f)
120→    {
121→      return 0;
122→    }
123→  if (fscanf(f, "%d %d %ld %d", &cups, &iv, &due, &goal) < 3)
124→    {
125→      fclose(f);
126→      return 0;
127→    }
128→  fclose(f);
129→  if (cups >= goal)
130→    {
131→      return 0;
132→    }
133→  return (due != 0 && time(NULL) >= (time_t)due) ? 1 : 0;
134→}
