136→void dm_proactive_tick(void)
137→{
138→  time_t now = time(NULL);
139→  struct tm tmv;
140→  int n;
141→
142→  localtime_r(&now, &tmv);
143→
144→  if (tmv.tm_hour == 8 && tmv.tm_min >= 30 && tmv.tm_min < 35 &&
145→      s_brief_ann_day != tmv.tm_yday)
146→    {
147→      s_brief_ann_day = tmv.tm_yday;
148→      say("brief.wav", "早上好。今天也要好好照顾自己");
149→      return;
150→    }
151→
152→  n = med_due_count();
153→  if (n > 0 && tmv.tm_hour != s_med_ann_hour)
154→    {
155→      s_med_ann_hour = tmv.tm_hour;
156→      say("med.wav", "该吃药了");
157→      return;
158→    }
159→
160→  if (water_due() && tmv.tm_min != s_water_ann_min)
161→    {
162→      s_water_ann_min = tmv.tm_min;
163→      say("water.wav", "喝水时间到");
164→    }
165→}
