891→
892→  /* Preserve the text answer even if playback fails; the caller can show
893→   * that the reply is text-only rather than pretending the speaker worked. */
894→  s_st = DM_VOICE_TTS;
895→  if (tts_synth(reply, WAV_TTS) == 0)
