1554→/****************************************************************************
1555→ * Name: ntpc_stop
1556→ *
1557→ * Description:
1558→ *   Stop the NTP daemon
1559→ *
1560→ * Returned Value:
1561→ *   Zero on success; a negated errno value on failure.  The current
1562→ *   implementation only returns success.
1563→ *
1564→ ****************************************************************************/
1565→
1566→int ntpc_stop(void)
1567→{
1568→  int ret;
1569→
1570→  /* Is the NTP in a running state? */
1571→
1572→  sem_wait(&g_ntpc_daemon.lock);
1573→  if (g_ntpc_daemon.state == NTP_STARTED ||
1574→      g_ntpc_daemon.state == NTP_RUNNING)
1575→    {
1576→      /* Yes.. request that the daemon stop. */
1577→
1578→      g_ntpc_daemon.state = NTP_STOP_REQUESTED;
1579→
1580→      /* Wait for any daemon state change */
1581→
1582→      do
1583→        {
1584→          /* Signal the NTP client */
1585→
1586→          ret = kill(g_ntpc_daemon.pid,
1587→                     CONFIG_NETUTILS_NTPCLIENT_SIGWAKEUP);
1588→
1589→          if (ret < 0)
1590→            {
1591→              nerr("ERROR: kill pid %d failed: %d\n",
1592→                   g_ntpc_daemon.pid, errno);
1593→              break;
1594→            }
1595→
1596→          /* Wait for the NTP client to respond to the stop request */
1597→
1598→          sem_wait(&g_ntpc_daemon.sync);
1599→        }
1600→      while (g_ntpc_daemon.state == NTP_STOP_REQUESTED);
1601→    }
1602→
1603→  sem_post(&g_ntpc_daemon.lock);
1604→  return OK;
1605→}
