static int wifi_clock_synced(void)
{
  struct ntpc_status_s status;
  struct tm utc;
  time_t now = time(NULL);

  if (now <= 0 || gmtime_r(&now, &utc) == NULL || utc.tm_year + 1900 < 2024)
    {
      return 0;
    }

  if (ntpc_status(&status) != 0 || status.nsamples == 0)
    {
      return 0;
    }

  return 1;
}

static void wifi_restart_ntp_after_link(void)
{
  int stop_rc;
  int start_rc;

  /* The boot-time daemon may have spent its exponential retry delay without
   * a network. Wake/restart it after WLAN gets a valid address. */
  stop_rc = ntpc_stop();
  start_rc = ntpc_start();
  syslog(start_rc < 0 ? LOG_WARNING : LOG_INFO,
         "[deskmate-wifi] NTP refresh requested stop=%d start=%d\n",
         stop_rc, start_rc);
}

int dm_wifi_wait_time_sync(int timeout_sec)
{
  int i;

  if (timeout_sec < 0)
    {
      timeout_sec = 0;
    }
  if (timeout_sec > 90)
    {
      timeout_sec = 90;
    }

  for (i = 0; i <= timeout_sec; i++)
    {
      if (wifi_clock_synced())
        {
          return 0;
        }
      if (!dm_wifi_connected())
        {
          return -ENETDOWN;
        }
      if (i < timeout_sec)
        {
          sleep(1);
        }
    }

  syslog(LOG_WARNING,
         "[deskmate-wifi] NTP time not ready; HTTPS request deferred\n");
  return -ETIMEDOUT;
}

