 158→int dm_voice_rec_stop(void)
 159→{
 160→  FILE *f;
 161→  long size;
 162→
 163→  pthread_mutex_lock(&s_rec_lock);
 164→  if (s_rec_active)
 165→    {
 166→      /* Stop/join can wait for the NuttX audio worker.  Keep this off the
 167→       * LVGL event thread and hold the audio gate until the recorder releases
 168→       * its DMA/session resources. */
 169→      pthread_mutex_lock(&s_audio_lock);
 170→      if (s_rec)
 171→        {
 172→          nxrecorder_stop(s_rec);
 173→          nxrecorder_release(s_rec);
 174→          s_rec = NULL;
 175→        }
 176→      s_rec_active = 0;
 177→      s_st = DM_VOICE_IDLE;
 178→      pthread_mutex_unlock(&s_audio_lock);
 179→    }
 180→  pthread_mutex_unlock(&s_rec_lock);
 181→
 182→  f = fopen(WAV_REC, "rb");
 183→  if (!f)
 184→    {
 185→      syslog(LOG_ERR, "[dm-voice] recording file missing\n");
 186→      s_st = DM_VOICE_ERR;
 187→      return -1;
 188→    }
 189→
 190→  if (fseek(f, 0, SEEK_END) != 0)
 191→    {
 192→      fclose(f);
 193→      s_st = DM_VOICE_ERR;
 194→      return -1;
 195→    }
 196→
 197→  size = ftell(f);
 198→  fclose(f);
 199→  if (size <= 44)
 200→    {
 201→      syslog(LOG_ERR, "[dm-voice] recording has no audio payload\n");
 202→      s_st = DM_VOICE_ERR;
 203→      return -1;
 204→    }
 205→
 206→  return 0;
 207→}
