 472→static const char b64tab[] =
 473→    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
 474→
 475→static int b64_encode(const unsigned char *in, size_t inlen, char *out, size_t outcap)
 476→{
 477→  size_t i = 0, o = 0;
 478→  while (i < inlen && o + 4 < outcap)
 479→    {
 480→      unsigned int v = in[i++] << 16;
 481→      if (i < inlen) v |= in[i++] << 8;
 482→      if (i < inlen) v |= in[i++];
 483→      out[o++] = b64tab[(v >> 18) & 63];
 484→      out[o++] = b64tab[(v >> 12) & 63];
 485→      out[o++] = b64tab[(v >> 6) & 63];
 486→      out[o++] = b64tab[v & 63];
 487→    }
 488→  out[o] = '\0';
 489→  return (int)o;
 490→}
 491→
 492→static int b64_decode(const char *in, unsigned char *out, size_t outcap)
 493→{
 494→  int val = 0, valb = -8;
 495→  size_t o = 0;
 496→  for (; *in && *in != '=' && o < outcap; in++)
 497→    {
 498→      const char *p = strchr(b64tab, *in);
 499→      if (!p) continue;
 500→      val = (val << 6) + (int)(p - b64tab);
 501→      valb += 6;
 502→      if (valb >= 0)
 503→        {
 504→          out[o++] = (unsigned char)((val >> valb) & 255);
 505→          valb -= 8;
 506→        }
 507→    }
 508→  return (int)o;
 509→}
