 542→static void put_le16(uint8_t *p, uint16_t value)
 543→{
 544→  p[0] = (uint8_t)value;
 545→  p[1] = (uint8_t)(value >> 8);
 546→}
 547→
 548→static void put_le32(uint8_t *p, uint32_t value)
 549→{
 550→  p[0] = (uint8_t)value;
 551→  p[1] = (uint8_t)(value >> 8);
 552→  p[2] = (uint8_t)(value >> 16);
 553→  p[3] = (uint8_t)(value >> 24);
 554→}
 555→
 556→/* nxrecorder's AUDIO_FMT_PCM encoder writes headerless PCM even when the
 557→ * filename ends in .wav.  Wrap that payload in a standards-compliant WAV
 558→ * header before sending `format: wav` to the MiMo chat-completions ASR API. */
 559→static int voice_prepare_wav(const char *src, const char **wav_out)
 560→{
 561→  FILE *in;
 562→  FILE *out;
 563→  uint8_t header[44];
 564→  char buf[1024];
 565→  long size;
 566→  size_t n;
 567→  uint32_t data_size;
 568→  unsigned int byte_rate = REC_RATE * REC_CH * REC_BITS / 8;
 569→  int rc = -1;
 570→
 571→  if (!src || !wav_out)
 572→    {
 573→      return -1;
 574→    }
 575→
 576→  *wav_out = src;
 577→  in = fopen(src, "rb");
 578→  if (!in)
 579→    {
 580→      return -1;
 581→    }
 582→
 583→  if (fread(header, 1, 12, in) == 12 &&
 584→      memcmp(header, "RIFF", 4) == 0 && memcmp(header + 8, "WAVE", 4) == 0)
 585→    {
 586→      fclose(in);
 587→      return 0;
 588→    }
 589→
 590→  if (fseek(in, 0, SEEK_END) != 0 || (size = ftell(in)) <= 0 ||
 591→      size > 2 * 1024 * 1024 - 44 || fseek(in, 0, SEEK_SET) != 0)
 592→    {
 593→      fclose(in);
 594→      return -1;
 595→    }
 596→
 597→  data_size = (uint32_t)size;
 598→  memset(header, 0, sizeof(header));
 599→  memcpy(header, "RIFF", 4);
 600→  put_le32(header + 4, data_size + 36);
 601→  memcpy(header + 8, "WAVEfmt ", 8);
 602→  put_le32(header + 16, 16);
 603→  put_le16(header + 20, 1);
 604→  put_le16(header + 22, REC_CH);
 605→  put_le32(header + 24, REC_RATE);
 606→  put_le32(header + 28, byte_rate);
 607→  put_le16(header + 32, REC_CH * REC_BITS / 8);
 608→  put_le16(header + 34, REC_BITS);
 609→  memcpy(header + 36, "data", 4);
 610→  put_le32(header + 40, data_size);
 611→
 612→  out = fopen(WAV_ASR, "wb");
 613→  if (!out)
 614→    {
 615→      fclose(in);
 616→      return -1;
 617→    }
 618→
 619→  if (fwrite(header, 1, sizeof(header), out) == sizeof(header))
 620→    {
 621→      rc = 0;
 622→      while ((n = fread(buf, 1, sizeof(buf), in)) > 0)
 623→        {
 624→          if (fwrite(buf, 1, n, out) != n)
 625→            {
 626→              rc = -1;
 627→              break;
 628→            }
 629→        }
 630→      if (ferror(in))
 631→        {
 632→          rc = -1;
 633→        }
 634→    }
 635→
 636→  if (fclose(out) != 0)
 637→    {
 638→      rc = -1;
 639→    }
 640→  fclose(in);
 641→  if (rc == 0)
 642→    {
 643→      *wav_out = WAV_ASR;
 644→    }
 645→  else
 646→    {
 647→      unlink(WAV_ASR);
 648→    }
 649→  return rc;
 650→}
 651→
 652→static int asr_wav(const char *wav, char *text, int cap)
 653→{
 654→  FILE *f;
 655→  unsigned char *raw;
 656→  char *b64;
 657→  char *body;
 658→  long sz;
 659→  int n;
 660→  char *p;
 661→  char *q;
 662→
 663→  text[0] = '\0';
 664→  f = fopen(wav, "rb");
 665→  if (!f)
 666→    {
 667→      return -1;
 668→    }
 669→  fseek(f, 0, SEEK_END);
 670→  sz = ftell(f);
 671→  fseek(f, 0, SEEK_SET);
 672→  if (sz <= 44 || sz > 2 * 1024 * 1024)
 673→    {
 674→      fclose(f);
 675→      return -1;
 676→    }
 677→  raw = malloc((size_t)sz);
 678→  b64 = malloc((size_t)sz * 2 + 8);
 679→  body = malloc((size_t)sz * 2 + 256);
 680→  if (!raw || !b64 || !body)
 681→    {
 682→      free(raw); free(b64); free(body); fclose(f);
 683→      return -1;
 684→    }
 685→  if (fread(raw, 1, (size_t)sz, f) != (size_t)sz)
 686→    {
 687→      free(raw); free(b64); free(body); fclose(f);
 688→      return -1;
 689→    }
 690→  fclose(f);
 691→  b64_encode(raw, (size_t)sz, b64, (size_t)sz * 2 + 8);
 692→  free(raw);
 693→
 694→  /* chat/completions ASR: input_audio */
 695→  n = snprintf(body, (size_t)sz * 2 + 256,
 696→               "{\"model\":\"%s\",\"messages\":[{\"role\":\"user\",\"content\":"
 697→               "[{\"type\":\"input_audio\",\"input_audio\":{\"data\":\"%s\","
 698→               "\"format\":\"wav\"}}]}]}",
 699→               ASR_MODEL, b64);
 700→  free(b64);
 701→  if (n <= 0)
 702→    {
 703→      free(body);
 704→      return -1;
 705→    }
 706→  if (http_post_json("/chat/completions", body, TXT_ASR) != 0)
 707→    {
 708→      free(body);
 709→      return -1;
 710→    }
 711→  free(body);
 712→
 713→  f = fopen(TXT_ASR, "rb");
 714→  if (!f)
 715→    {
 716→      return -1;
 717→    }
 718→  fseek(f, 0, SEEK_END);
 719→  sz = ftell(f);
 720→  fseek(f, 0, SEEK_SET);
 721→  if (sz <= 0 || sz > 256 * 1024)
 722→    {
 723→      fclose(f);
 724→      return -1;
 725→    }
 726→  body = malloc((size_t)sz + 1);
 727→  if (!body)
 728→    {
 729→      fclose(f);
 730→      return -1;
 731→    }
 732→  if (fread(body, 1, (size_t)sz, f) != (size_t)sz)
 733→    {
 734→      free(body);
 735→      fclose(f);
 736→      return -1;
 737→    }
 738→  body[sz] = '\0';
 739→  fclose(f);
 740→
 741→  p = strstr(body, "\"content\"");
 742→  if (p)
 743→    {
 744→      p = strchr(p + 9, '"');
 745→      if (p)
 746→        {
 747→          q = strchr(p + 1, '"');
 748→          if (q)
 749→            {
 750→              size_t ln = (size_t)(q - p - 1);
 751→              if (ln >= (size_t)cap)
 752→                {
 753→                  ln = (size_t)cap - 1;
 754→                }
 755→              memcpy(text, p + 1, ln);
 756→              text[ln] = '\0';
 757→            }
 758→        }
 759→    }
 760→  free(body);
 761→  return text[0] ? 0 : -1;
 762→}
