123→static int json_escape(const char *in, char *out, size_t cap)
124→{
125→  size_t o = 0;
126→  size_t i;
127→
128→  if (!in || !out || cap < 2)
129→    {
130→      return -1;
131→    }
132→  for (i = 0; in[i] && o + 8 < cap; i++)
133→    {
134→      unsigned char ch = (unsigned char)in[i];
135→      if (ch == '"' || ch == '\\')
136→        {
137→          out[o++] = '\\';
138→          out[o++] = (char)ch;
139→        }
140→      else if (ch == '\n')
141→        {
142→          out[o++] = '\\';
143→          out[o++] = 'n';
144→        }
145→      else if (ch < 0x20)
146→        {
147→          /* skip control chars */
148→        }
149→      else
150→        {
151→          out[o++] = (char)ch;
152→        }
153→    }
154→  out[o] = '\0';
155→  return (int)o;
156→}
