365→const char *dm_chat_ai_ask(const char *user_text)
366→{
367→  char esc[400];
368→  char hist[1400];
369→  char body[2400];
370→  char cmd[1200];
371→  FILE *f;
372→  int n;
373→
374→  s_last_reply[0] = '\0';
375→  s_last_request_remote_ok = 0;
376→  if (!user_text || !user_text[0])
377→    {
378→      return local_reply("");
379→    }
380→
381→  if (!dm_wifi_connected())
382→    {
383→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
384→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
385→      return s_last_reply;
386→    }
387→
388→  /* Do not send HTTPS while the board clock is still at its boot epoch;
389→   * this causes mbedTLS to reject valid certificates as not-yet-valid. */
390→  if (dm_wifi_wait_time_sync(40) != 0)
391→    {
392→      syslog(LOG_WARNING, "[dm-chat] system clock not synchronized\n");
393→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
394→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
395→      return s_last_reply;
396→    }
397→
398→  if (json_escape(user_text, esc, sizeof(esc)) < 0)
399→    {
400→      return local_reply(user_text);
401→    }
402→
403→  dm_chat_hist_json(hist, sizeof(hist));
404→  n = snprintf(body, sizeof(body),
405→               "{\"model\":\"%s\",\"messages\":["
406→               "{\"role\":\"system\",\"content\":\"%s\"},"
407→               "%s"
408→               "{\"role\":\"user\",\"content\":\"%s\"}],"
409→               "\"temperature\":0.7,\"max_tokens\":400}",
410→               MIMO_MODEL,
411→               s_persona_ctx[0] ? s_persona_ctx
412→                                 : "你是openvela小助手，桌边陪伴助手，回答简洁温暖，"
413→                                   "不超过80字，用中文。",
414→               hist, esc);
415→  if (n <= 0 || n >= (int)sizeof(body))
416→    {
417→      return local_reply(user_text);
418→    }
419→
420→  f = fopen(CHAT_REQ_PATH, "w");
421→  if (!f)
422→    {
423→      return local_reply(user_text);
424→    }
425→  fwrite(body, 1, (size_t)n, f);
426→  fclose(f);
427→
428→  unlink(CHAT_RSP_PATH);
429→  /* The board curl CLI rejects long options such as --cacert. */
430→  snprintf(cmd, sizeof(cmd),
431→           "curl -s -S -m 20 -X POST %s/chat/completions "
432→           "-H 'Authorization: Bearer %s' "
433→           "-H 'Content-Type: application/json' "
434→           "-d @%s -o %s",
435→           MIMO_BASE, MIMO_KEY, CHAT_REQ_PATH, CHAT_RSP_PATH);
436→  if (run_curl_script(cmd) != 0)
437→    {
438→      strncpy(s_last_reply, local_reply(user_text),
439→              sizeof(s_last_reply) - 1);
440→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
441→      return s_last_reply;
442→    }
443→
444→  extract_content(CHAT_RSP_PATH, s_last_reply, sizeof(s_last_reply));
445→  if (s_last_reply[0])
446→    {
447→      s_last_request_remote_ok = 1;
448→      dm_chat_hist_push(user_text, s_last_reply);
449→    }
450→  else
451→    {
452→      strncpy(s_last_reply, local_reply(user_text),
453→              sizeof(s_last_reply) - 1);
454→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
455→    }
456→  return s_last_reply;
457→}
