 206→/* NSH-safe single-quote wrap; reject embedded single quotes */
 207→static int shell_quote(const char *in, char *out, size_t outsz)
 208→{
 209→  size_t n;
 210→  size_t o = 0;
 211→
 212→  if (!in || !out || outsz < 3)
 213→    {
 214→      return -1;
 215→    }
 216→  if (strchr(in, '\'') != NULL)
 217→    {
 218→      return -1;
 219→    }
 220→  n = strlen(in);
 221→  if (n + 3 > outsz)
 222→    {
 223→      return -1;
 224→    }
 225→  out[o++] = '\'';
 226→  memcpy(out + o, in, n);
 227→  o += n;
 228→  out[o++] = '\'';
 229→  out[o] = 0;
 230→  return 0;
 231→}
