 253→static int wifi_clock_synced(void)
 254→{
 255→  struct ntpc_status_s status;
 256→  struct tm utc;
 257→  time_t now = time(NULL);
 258→
 259→  if (now <= 0 || gmtime_r(&now, &utc) == NULL || utc.tm_year + 1900 < 2024)
 260→    {
 261→      return 0;
 262→    }
 263→
 264→  if (ntpc_status(&status) != 0 || status.nsamples == 0)
 265→    {
 266→      return 0;
 267→    }
 268→
 269→  return 1;
 270→}
