 551→static int wifi_cred_load_cfg(char *ssid, size_t slen, char *pass,
 552→                              size_t plen)
 553→{
 554→  FILE *f = fopen("/data/wifi.cfg", "r");
 555→  char line[96];
 556→  int got_ssid = 0;
 557→  int got_pass = 0;
 558→
 559→  if (!f)
 560→    {
 561→      return -1;
 562→    }
 563→  while (fgets(line, sizeof(line), f))
 564→    {
 565→      line[strcspn(line, "\r\n")] = 0;
 566→      if (strncmp(line, "SSID=", 5) == 0)
 567→        {
 568→          snprintf(ssid, slen, "%s", line + 5);
 569→          wifi_unquote(ssid);
 570→          got_ssid = 1;
 571→        }
 572→      else if (strncmp(line, "PASSWORD=", 9) == 0)
 573→        {
 574→          snprintf(pass, plen, "%s", line + 9);
 575→          wifi_unquote(pass);
 576→          got_pass = 1;
 577→        }
 578→    }
 579→  fclose(f);
 580→
 581→  if (!got_ssid || !ssid[0])
 582→    {
 583→      return -1;
 584→    }
 585→  if (!got_pass)
 586→    {
 587→      pass[0] = 0;
 588→    }
 589→  syslog(LOG_INFO, "[deskmate-wifi] creds from /data/wifi.cfg ssid=%s\n",
 590→         ssid);
 591→  return 0;
 592→}
