 741→
 742→/* Parse /tmp/wifi_scan_result.txt:
 743→ *   bssid / frequency / signal level / encode / ssid
 744→ *   74:39:89:f8:f0:ae       5240    -59     0803    Programmers7
 745→ *   d2:ad:08:f8:eb:71       2462    -88     0803    DIRECT-71-HP Smart Tank 750
 746→ *
 747→ * Preserves spaces inside SSIDs, skips hidden (empty) SSIDs and non-MAC lines,
 748→ * deduplicates same-SSID entries (keeping strongest RSSI), and sorts by RSSI.
 749→ */
 750→static int collect_aps_from_txt(void)
 751→{
 752→  FILE *fp;
 753→  char line[256];
 754→  int n = 0;
 755→  int i;
 756→  int j;
 757→
 758→  fp = fopen("/tmp/wifi_scan_result.txt", "r");
 759→  if (!fp)
 760→    {
 761→      return -1;
 762→    }
 763→
 764→  pthread_mutex_lock(&s_lock);
 765→  s_ap_n = 0;
 766→
 767→  while (fgets(line, sizeof(line), fp) && n < DM_WIFI_AP_MAX)
 768→    {
 769→      char *p = line;
 770→      char *tok_bssid;
 771→      char *tok_freq;
 772→      char *tok_rssi;
 773→      char *tok_enc;
 774→      char *ssid_start;
 775→      size_t ssid_len;
 776→      int rssi;
 777→      bool is_open;
 778→      int dup_idx = -1;
 779→
 780→      line[strcspn(line, "\r\n")] = 0;
 781→
 782→      while (*p == ' ' || *p == '\t')
 783→        {
 784→          p++;
 785→        }
 786→      if (!*p || strncmp(p, "bssid", 5) == 0)
 787→        {
 788→          continue;
 789→        }
 790→
 791→      /* Field 0: BSSID (must contain ':') */
 792→      tok_bssid = p;
 793→      while (*p && *p != ' ' && *p != '\t')
 794→        {
 795→          p++;
 796→        }
 797→      if (!*p)
 798→        {
 799→          continue;
 800→        }
 801→      *p++ = 0;
 802→      if (strchr(tok_bssid, ':') == NULL)
 803→        {
 804→          continue;
 805→        }
 806→
 807→      /* Field 1: frequency */
 808→      while (*p == ' ' || *p == '\t')
 809→        {
 810→          p++;
 811→        }
 812→      tok_freq = p;
 813→      while (*p && *p != ' ' && *p != '\t')
 814→        {
 815→          p++;
 816→        }
 817→      if (!*p || !*tok_freq)
 818→        {
 819→          continue;
 820→        }
 821→      *p++ = 0;
 822→
 823→      /* Field 2: signal level (RSSI) */
 824→      while (*p == ' ' || *p == '\t')
 825→        {
 826→          p++;
 827→        }
 828→      tok_rssi = p;
 829→      while (*p && *p != ' ' && *p != '\t')
 830→        {
 831→          p++;
 832→        }
 833→      if (!*p || !*tok_rssi)
 834→        {
 835→          continue;
 836→        }
 837→      *p++ = 0;
 838→      rssi = atoi(tok_rssi);
 839→
 840→      /* Field 3: encode (0000 = open, otherwise encrypted) */
 841→      while (*p == ' ' || *p == '\t')
 842→        {
 843→          p++;
 844→        }
 845→      tok_enc = p;
 846→      while (*p && *p != ' ' && *p != '\t')
 847→        {
 848→          p++;
 849→        }
 850→      if (*p)
 851→        {
 852→          *p++ = 0;
 853→        }
 854→      if (!*tok_enc)
 855→        {
 856→          continue;
 857→        }
 858→      is_open = (strcmp(tok_enc, "0000") == 0);
 859→
 860→      /* Field 4+: entire remainder of line is SSID (may contain spaces) */
 861→      while (*p == ' ' || *p == '\t')
 862→        {
 863→          p++;
 864→        }
 865→      ssid_start = p;
 866→      ssid_len = strlen(ssid_start);
 867→      while (ssid_len > 0 &&
 868→             (ssid_start[ssid_len - 1] == ' ' ||
 869→              ssid_start[ssid_len - 1] == '\t'))
 870→        {
 871→          ssid_start[--ssid_len] = 0;
 872→        }
 873→      if (ssid_len == 0)
 874→        {
 875→          /* Hidden AP with blank SSID */
 876→          continue;
 877→        }
 878→
 879→      /* Deduplicate by SSID: keep strongest RSSI */
 880→      for (i = 0; i < n; i++)
 881→        {
 882→          if (strncmp(s_aps[i].ssid, ssid_start, sizeof(s_aps[i].ssid) - 1) == 0)
 883→            {
 884→              dup_idx = i;
 885→              break;
 886→            }
 887→        }
 888→      if (dup_idx >= 0)
 889→        {
 890→          if (rssi > s_aps[dup_idx].rssi)
 891→            {
 892→              s_aps[dup_idx].rssi = rssi;
 893→              s_aps[dup_idx].open = is_open;
 894→            }
 895→          continue;
 896→        }
 897→
 898→      strncpy(s_aps[n].ssid, ssid_start, sizeof(s_aps[n].ssid) - 1);
 899→      s_aps[n].ssid[sizeof(s_aps[n].ssid) - 1] = 0;
 900→      s_aps[n].rssi = rssi;
 901→      s_aps[n].open = is_open;
 902→      n++;
 903→    }
 904→
 905→  /* Sort APs by RSSI descending (strongest signal first) */
 906→  for (i = 0; i < n - 1; i++)
 907→    {
 908→      for (j = i + 1; j < n; j++)
 909→        {
 910→          if (s_aps[j].rssi > s_aps[i].rssi)
 911→            {
 912→              dm_ap_t tmp = s_aps[i];
 913→              s_aps[i] = s_aps[j];
 914→              s_aps[j] = tmp;
 915→            }
 916→        }
 917→    }
 918→
 919→  s_ap_n = n;
 920→  if (s_sel >= s_ap_n)
 921→    {
 922→      s_sel = (s_ap_n > 0) ? 0 : -1;
 923→    }
 924→  pthread_mutex_unlock(&s_lock);
 925→  fclose(fp);
 926→  return n;
 927→}
 928→
 929→static void *scan_thread(void *arg)
 930→{
 931→  int i;
 932→  int n;
 933→
 934→  (void)arg;
 935→
 936→  if (!s_wifi_enabled)
 937→    {
 938→      s_scan_busy = 0;
 939→      s_scan_ready = 1;
 940→      return NULL;
 941→    }
 942→
 943→  /* Wait briefly if an auto-connect thread is yielding */
 944→  for (i = 0; i < 50 && s_conn_busy; i++)
 945→    {
 946→      usleep(100 * 1000);
 947→    }
 948→
 949→  if (ensure_driver() < 0)
 950→    {
 951→      s_scan_busy = 0;
 952→      s_scan_ready = 1;
 953→      return NULL;
 954→    }
 955→
 956→  /* Only bring interface up in STA mode if not already connected */
 957→  if (!dm_wifi_connected())
 958→    {
 959→      cli_sta_up();
 960→      usleep(200 * 1000);
 961→    }
 962→
 963→  /* Match 9.5 demo get_wifi.sh: wapi scan wlan0 > /tmp/wifi_scan_result.txt */
 964→  (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
 965→  usleep(300 * 1000);
 966→
 967→  n = collect_aps_from_txt();
 968→  if (n <= 0)
 969→    {
 970→      usleep(500 * 1000);
 971→      (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
 972→      usleep(300 * 1000);
 973→      n = collect_aps_from_txt();
 974→    }
 975→
 976→  syslog(LOG_INFO, "[deskmate-wifi] wapi scan -> %d aps\n", n);
 977→  for (i = 0; i < s_ap_n; i++)
 978→    {
 979→      syslog(LOG_INFO, "[deskmate-wifi]  ap %s rssi=%d open=%d\n",
 980→             s_aps[i].ssid, s_aps[i].rssi, (int)s_aps[i].open);
 981→    }
 982→
 983→  s_scan_busy = 0;
 984→  s_scan_ready = 1;
 985→  return NULL;
 986→}
 987→
 988→int dm_wifi_start_scan(void)
 989→{
 990→  pthread_t th;
 991→  pthread_attr_t attr;
 992→  int ret;
 993→
 994→  if (!s_wifi_enabled)
 995→    {
 996→      return -1;
 997→    }
 998→
 999→  if (s_scan_busy)
1000→    {
1001→      return 0;
1002→    }
1003→
1004→  /* Interrupt any background boot auto-connect so manual scan is never blocked */
1005→  s_manual_override = 1;
1006→  if (s_conn_busy && !s_conn_is_auto)
1007→    {
1008→      return -1;
1009→    }
1010→
1011→  s_scan_ready = 0;
1012→  s_scan_busy = 1;
1013→  pthread_attr_init(&attr);
1014→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1015→  ret = pthread_create(&th, &attr, scan_thread, NULL);
1016→  pthread_attr_destroy(&attr);
1017→  if (ret != 0)
1018→    {
1019→      s_scan_busy = 0;
1020→      return -1;
1021→    }
1022→  pthread_detach(th);
1023→  return 0;
1024→}
1025→
1026→/* Official connect — ifup → mode 2 → psk(3 2) → essid(1) → wait → renew */
1027→static void *conn_thread(void *arg)
1028→{
1029→  char cmd[192];
1030→  char qssid[80];
1031→  char qpass[160];
1032→  int i;
1033→  int attempt;
1034→  int got_ip = 0;
1035→  int is_auto = s_conn_is_auto;
1036→  struct in_addr addr;
1037→  char try_ssid[33];
1038→  char try_pass[64];
1039→  bool try_open;
1040→
1041→  (void)arg;
1042→
1043→  if (!s_wifi_enabled)
1044→    {
1045→      s_conn_busy = 0;
1046→      s_conn_fail = 1;
1047→      return NULL;
1048→    }
1049→
1050→  strncpy(try_ssid, s_pending_ssid, sizeof(try_ssid) - 1);
1051→  try_ssid[sizeof(try_ssid) - 1] = 0;
1052→  strncpy(try_pass, s_pending_pass, sizeof(try_pass) - 1);
1053→  try_pass[sizeof(try_pass) - 1] = 0;
1054→  try_open = s_pending_open;
1055→
1056→  if (try_ssid[0] == 0 || if_nametoindex(DM_WIFI_IF) == 0)
1057→    {
1058→      syslog(LOG_ERR, "[deskmate-wifi] connect abort: no ssid/wlan0\n");
1059→      s_conn_busy = 0;
1060→      s_conn_fail = 1;
1061→      return NULL;
1062→    }
1063→
1064→  if (ensure_driver() < 0)
1065→    {
1066→      s_conn_busy = 0;
1067→      s_conn_fail = 1;
1068→      return NULL;
1069→    }
1070→
1071→  if (is_auto && s_manual_override)
1072→    {
1073→      s_conn_busy = 0;
1074→      return NULL;
1075→    }
1076→
1077→  /* NOTE: credentials are persisted only after a verified connection (below).
1078→
1079→   * 9) The 9.5 wifi_manager retries the whole sequence every 5s until it is
1080→   * associated. Port that behaviour here: up to DM_WIFI_CONN_ROUNDS tries. */
1081→  for (attempt = 0; attempt < DM_WIFI_CONN_ROUNDS; attempt++)
1082→    {
1083→      if (attempt > 0)
1084→        {
1085→          syslog(LOG_INFO, "[deskmate-wifi] retry %d/%d in %ds\n",
1086→                 attempt + 1, DM_WIFI_CONN_ROUNDS, DM_WIFI_CONN_RETRY_SEC);
1087→          sleep(DM_WIFI_CONN_RETRY_SEC);
1088→        }
1089→
1090→      got_ip = 0;
1091→
1092→      /* 1) ifup + STA mode */
1093→      cli_sta_up();
1094→
1095→  /* 1.5) Drop the previous association so switching between networks
1096→   *      (WPA2 <-> open) always starts from a clean driver state. */
1097→  syslog(LOG_INFO, "[deskmate-wifi] wapi disconnect %s\n", DM_WIFI_IF);
1098→  (void)system("wapi disconnect wlan0");
1099→  usleep(100 * 1000);
1100→
1101→  /* 2) psk — WPA_ALG_CCMP = 3, WPA2 = 2 */
1102→  if (!try_open && try_pass[0])
1103→    {
1104→      if (shell_quote(try_pass, qpass, sizeof(qpass)) < 0)
1105→        {
1106→          s_conn_busy = 0;
1107→          s_conn_fail = 1;
1108→          return NULL;
1109→        }
1110→      snprintf(cmd, sizeof(cmd), "wapi psk %s %s 3 2", DM_WIFI_IF, qpass);
1111→      syslog(LOG_INFO,
1112→             "[deskmate-wifi] applying WPA2 credentials (redacted)\n");
1113→      if (system(cmd) != 0)
1114→        {
1115→          syslog(LOG_ERR, "[deskmate-wifi] psk failed (passphrase must be 8-63 chars)\n");
1116→          s_conn_busy = 0;
1117→          s_conn_fail = 1;
1118→          return NULL;
1119→        }
1120→    }
1121→  else
1122→    {
1123→      /* Open AP: clear any leftover WPA key (alg 0 = WPA_ALG_NONE), otherwise
1124→       * the driver keeps the previous CCMP key and cannot join open networks. */
1125→      syslog(LOG_INFO, "[deskmate-wifi] open AP: clear psk\n");
1126→      (void)system("wapi psk wlan0 00000000 0");
1127→    }
1128→
1129→  /* 3) essid — flag 1 = connect */
1130→  if (shell_quote(try_ssid, qssid, sizeof(qssid)) < 0)
1131→    {
1132→      s_conn_busy = 0;
1133→      s_conn_fail = 1;
1134→      return NULL;
1135→    }
1136→  snprintf(cmd, sizeof(cmd), "wapi essid %s %s 1", DM_WIFI_IF, qssid);
1137→  syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
1138→  if (system(cmd) != 0)
1139→    {
1140→      syslog(LOG_ERR, "[deskmate-wifi] essid join failed\n");
1141→      s_conn_busy = 0;
1142→      s_conn_fail = 1;
1143→      return NULL;
1144→    }
1145→
1146→  /* 4) Wait for WPA2 4-way handshake / association (interruptible if auto) */
1147→  for (i = 0; i < 25; i++)
1148→    {
1149→      if (!s_wifi_enabled)
1150→        {
1151→          s_conn_busy = 0;
1152→          return NULL;
1153→        }
1154→      if (is_auto && s_manual_override)
1155→        {
1156→          s_conn_busy = 0;
1157→          return NULL;
1158→        }
1159→      usleep(100 * 1000);
1160→    }
1161→
1162→  /* 5) DHCP renew — single DHCP call per attempt */
1163→  for (i = 0; i < 4; i++)
1164→    {
1165→      if (is_auto && s_manual_override)
1166→        {
1167→          s_conn_busy = 0;
1168→          return NULL;
1169→        }
1170→
1171→      (void)system("renew wlan0");
1172→      if (wifi_get_valid_ip(&addr) == 0)
1173→        {
1174→          got_ip = 1;
1175→          break;
1176→        }
1177→
1178→      if (is_auto && s_manual_override)
1179→        {
1180→          s_conn_busy = 0;
1181→          return NULL;
1182→        }
1183→
1184→      if (netlib_obtain_ipv4addr(DM_WIFI_IF) >= 0 &&
1185→          wifi_get_valid_ip(&addr) == 0)
1186→        {
1187→          got_ip = 1;
1188→          break;
1189→        }
1190→
1191→      syslog(LOG_WARNING, "[deskmate-wifi] renew retry %d\n", i + 1);
1192→      sleep(1);
1193→    }
1194→
1195→  /* Verify we are really associated with the intended SSID (an old IPv4
1196→   * address may still be configured while switching networks). */
1197→  if (got_ip)
1198→    {
1199→      int assoc = wifi_verify_assoc(try_ssid);
1200→      if (assoc == 0)
1201→        {
1202→          syslog(LOG_ERR,
1203→                 "[deskmate-wifi] associated to another SSID, treat as failure\n");
1204→          got_ip = 0;
1205→        }
1206→      else if (assoc < 0)
1207→        {
1208→          syslog(LOG_WARNING,
1209→                 "[deskmate-wifi] cannot verify ESSID, assume connected\n");
1210→        }
1211→    }
1212→
1213→      /* Ported check: "wapi show" reports AP all-zero when not associated. */
1214→      if (got_ip && wifi_is_link_up() == 0)
1215→        {
1216→          syslog(LOG_WARNING, "[deskmate-wifi] wapi show: not associated yet\n");
1217→          got_ip = 0;
1218→        }
1219→
1220→      if (got_ip)
1221→        {
1222→          break;
1223→        }
1224→
1225→      syslog(LOG_WARNING, "[deskmate-wifi] attempt %d/%d failed\n",
1226→             attempt + 1, DM_WIFI_CONN_ROUNDS);
1227→    }
1228→
1229→  if (got_ip && !s_wifi_enabled)
1230→    {
1231→      got_ip = 0;
1232→    }
1233→
1234→  /* Fix: Only set s_cur_ssid when got_ip is true! */
1235→  pthread_mutex_lock(&s_lock);
1236→  if (got_ip)
1237→    {
1238→      strncpy(s_cur_ssid, try_ssid, sizeof(s_cur_ssid) - 1);
1239→      s_cur_ssid[sizeof(s_cur_ssid) - 1] = 0;
1240→      strncpy(s_cur_ip, inet_ntoa(addr), sizeof(s_cur_ip) - 1);
1241→      s_cur_ip[sizeof(s_cur_ip) - 1] = 0;
1242→    }
1243→  else
1244→    {
1245→      s_cur_ssid[0] = 0;
1246→      s_cur_ip[0] = 0;
1247→    }
1248→  pthread_mutex_unlock(&s_lock);
1249→
1250→  if (!got_ip)
1251→    {
1252→      syslog(LOG_ERR,
1253→             "[deskmate-wifi] connect fail after %d attempts "
1254→             "(ssid=%s wlan0=%d)\n",
1255→             DM_WIFI_CONN_ROUNDS, try_ssid,
1256→             (int)if_nametoindex(DM_WIFI_IF));
1257→      s_conn_busy = 0;
1258→      s_conn_fail = 1;
1259→      return NULL;
1260→    }
1261→
1262→  syslog(LOG_INFO, "[deskmate-wifi] connected ssid=%s ip=%s\n",
1263→         s_cur_ssid, s_cur_ip);
1264→
1265→  /* FlowDesk owns credential persistence; let NTP start only after WLAN
1266→   * has a verified association and an IPv4 address. */
1267→  wifi_cred_save(try_ssid, try_pass);
1268→  s_manual_override = 0;
1269→  s_link_lost = 0;
1270→  if (!wifi_clock_synced())
1271→    {
1272→      wifi_restart_ntp_after_link();
1273→    }
1274→
1275→  s_conn_busy = 0;
1276→  s_conn_ok = 1;
1277→  return NULL;
1278→}
1279→
1280→static int wifi_start_connect_internal(const char *ssid, const char *pass,
1281→                                       int is_auto)
1282→{
1283→  pthread_t th;
1284→  pthread_attr_t attr;
1285→  int ret;
1286→  int i;
1287→
1288→  if (!ssid || !ssid[0])
1289→    {
1290→      return -1;
1291→    }
1292→
1293→  if (!is_auto)
1294→    {
1295→      s_manual_override = 1;
1296→      for (i = 0; i < 50 && (s_scan_busy || (s_conn_busy && s_conn_is_auto)); i++)
1297→        {
1298→          usleep(100 * 1000);
1299→        }
1300→    }
1301→
1302→  if (s_scan_busy || s_conn_busy)
1303→    {
1304→      return -1;
1305→    }
1306→
1307→  strncpy(s_pending_ssid, ssid, sizeof(s_pending_ssid) - 1);
1308→  s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
1309→  if (pass)
1310→    {
1311→      strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
1312→      s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
1313→    }
1314→  else
1315→    {
1316→      s_pending_pass[0] = 0;
1317→    }
1318→  s_pending_open = (pass == NULL || s_pending_pass[0] == 0);
1319→
1320→  s_conn_ok = 0;
1321→  s_conn_fail = 0;
1322→  s_conn_is_auto = is_auto;
1323→  s_conn_busy = 1;
1324→
1325→  pthread_attr_init(&attr);
1326→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1327→  ret = pthread_create(&th, &attr, conn_thread, NULL);
1328→  pthread_attr_destroy(&attr);
1329→  if (ret != 0)
1330→    {
1331→      s_conn_busy = 0;
1332→      return -1;
1333→    }
1334→  pthread_detach(th);
1335→  return 0;
1336→}
1337→
1338→int dm_wifi_connect(const char *ssid, const char *pass)
1339→{
1340→  return wifi_start_connect_internal(ssid, pass, 0);
1341→}
