1429→/* Boot auto-connect: checks if already connected, otherwise tries saved
1430→ * credentials once or twice and immediately yields if user opens manual scan. */
1431→static void *auto_thread(void *arg)
1432→{
1433→  char ssid[33];
1434→  char pass[64];
1435→  struct in_addr addr;
1436→  int round;
1437→  int i;
1438→
1439→  (void)arg;
1440→
1441→  ssid[0] = 0;
1442→  pass[0] = 0;
1443→  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
1444→      !ssid[0])
1445→    {
1446→      if (DM_WIFI_AUTO_SSID[0] == 0)
1447→        {
1448→          syslog(LOG_INFO,
1449→                 "[deskmate-wifi] no saved credentials; skip boot connect\n");
1450→          goto done;
1451→        }
1452→      snprintf(ssid, sizeof(ssid), "%s", DM_WIFI_AUTO_SSID);
1453→      snprintf(pass, sizeof(pass), "%s", DM_WIFI_AUTO_PSK);
1454→    }
1455→
1456→  syslog(LOG_INFO,
1457→         "[deskmate-wifi] auto-connect ssid=%s — wait wlan0 first\n", ssid);
1458→
1459→  for (round = 0; round < 2 && !s_manual_override; round++)
1460→    {
1461→      if (ensure_driver_wait(300) < 0)
1462→        {
1463→          if (s_manual_override)
1464→            {
1465→              goto done;
1466→            }
1467→          sleep(2);
1468→          continue;
1469→        }
1470→
1471→      /* Ignore placeholder addresses unless association to the saved AP is
1472→       * verified; wlan0 may report 10.0.0.2 while its AP MAC is still zero. */
1473→      if (wifi_get_valid_ip(&addr) == 0 &&
1474→          wifi_verify_assoc(ssid) == 1 && wifi_is_link_up() == 1)
1475→        {
1476→          pthread_mutex_lock(&s_lock);
1477→          snprintf(s_cur_ssid, sizeof(s_cur_ssid), "%s", ssid);
1478→          snprintf(s_cur_ip, sizeof(s_cur_ip), "%s", inet_ntoa(addr));
1479→          pthread_mutex_unlock(&s_lock);
1480→          syslog(LOG_INFO, "[deskmate-wifi] already connected ssid=%s ip=%s\n",
1481→                 s_cur_ssid, s_cur_ip);
1482→          wifi_cred_save(ssid, pass);
1483→          if (!wifi_clock_synced())
1484→            {
1485→              wifi_restart_ntp_after_link();
1486→            }
1487→          goto done;
1488→        }
1489→
1490→      if (dm_wifi_connected() || s_manual_override)
1491→        {
1492→          goto done;
1493→        }
1494→
1495→      dm_wifi_clear_conn_flags();
1496→      if (wifi_start_connect_internal(ssid, pass, 1) != 0)
1497→        {
1498→          sleep(2);
1499→          continue;
1500→        }
1501→
1502→      /* Wait for conn_thread to finish or manual override */
1503→      for (i = 0; i < 600 && s_conn_busy && !s_manual_override; i++)
1504→        {
1505→          usleep(100 * 1000);
1506→        }
1507→
1508→      if (dm_wifi_connected())
1509→        {
1510→          syslog(LOG_INFO, "[deskmate-wifi] auto connected ssid=%s ip=%s\n",
1511→                 dm_wifi_cur_ssid(), dm_wifi_cur_ip());
1512→          dm_wifi_clear_conn_flags();
1513→          goto done;
1514→        }
1515→
1516→      dm_wifi_clear_conn_flags();
1517→      if (s_manual_override)
1518→        {
1519→          goto done;
1520→        }
1521→      sleep(2);
1522→    }
1523→
1524→  syslog(LOG_INFO,
1525→         "[deskmate-wifi] auto-connect finished; manual UI ready\n");
1526→done:
1527→  s_auto_thread_active = 0;
1528→  return NULL;
1529→}
1530→
1531→/* Boot auto-connect: reads saved credentials (/data/deskmate_wifi.txt or
1532→ * /data/wifi.cfg) and reconnects, yielding to the manual UI if the user
1533→ * starts a scan/connect first.  Called once from deskmate_main.c. */
1534→void dm_wifi_auto_start(void)
1535→{
1536→  pthread_t th;
1537→  pthread_attr_t attr;
1538→
1539→  if (s_auto_started)
1540→    {
1541→      return;
1542→    }
1543→  s_auto_started = 1;
1544→  s_auto_thread_active = 1;
1545→
1546→  pthread_attr_init(&attr);
1547→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1548→  if (pthread_create(&th, &attr, auto_thread, NULL) == 0)
1549→    {
1550→      pthread_detach(th);
1551→    }
1552→  else
1553→    {
1554→      s_auto_thread_active = 0;
1555→    }
1556→  pthread_attr_destroy(&attr);
1557→}
