362→void dm_chat_tick(void)
363→{
364→  /* apply worker results on LVGL thread */
365→  if (s_out_ready)
366→    {
367→      s_out_ready = 0;
368→      if (s_out_ans[0])
369→        {
370→          set_ans(s_out_ans);
371→        }
372→      if (s_out_sub[0])
373→        {
374→          set_sub(s_out_sub);
375→        }
376→      dm_face_set(FACE_HAPPY, EYE_DECOR_NONE, 8);
377→      reset_to_idle();
378→    }
379→
380→  if (s_ui_rec && !s_busy)
381→    {
382→      char buf[80];
383→      uint64_t now_ms = chat_monotonic_ms();
384→      if (s_rec_started_ms != 0 && now_ms >= s_rec_started_ms)
385→        {
386→          s_rec_sec = (int)((now_ms - s_rec_started_ms) / 1000);
387→        }
388→      if (dm_voice_rec_active())
389→        {
390→          snprintf(buf, sizeof(buf),
391→                   dm_t("● 录音中 %d 秒 · 再点一下结束并发送",
392→                        "● Recording %ds · tap again to send"),
393→                   s_rec_sec);
394→          set_ans(buf);
395→          set_sub((s_rec_sec & 1) ? dm_t("正在听…", "Listening…")
396→                                  : dm_t("对准麦克风说话", "Speak to the mic"));
397→        }
398→      else
399→        {
400→          s_ui_rec = false;
401→          if (s_rec_sec < 2)
402→            {
403→              s_mic_err = 1;
404→              set_ans(dm_t("麦克风故障，无法录音", "Mic failed"));
405→              set_sub(dm_t("检查 /dev/audio/pcm0c", "Check mic device"));
406→              reset_to_idle();
407→            }
408→          else
409→            {
410→              /* Recording auto-stop reached the configured limit.  Send the
411→               * captured WAV instead of silently discarding it. */
412→              kick_job(1);
413→            }
414→        }
415→    }
416→}
