1280→   * initially.  Solutions:
1281→   *
1282→   * 1. Fix send logic so that it assures that the ARP request has been
1283→   *    sent and the entry is in the ARP table before sending the packet
1284→   *    (best).
1285→   * 2. Add some ad hoc logic here so that there is no delay until at least
1286→   *    one good time is received.
1287→   */
1288→
1289→  sched_lock();
1290→  while (g_ntpc_daemon.state != NTP_STOP_REQUESTED)
1291→    {
1292→      struct timespec start_realtime;
1293→      struct timespec start_monotonic;
1294→      int errval = 0;
1295→      int i;
1296→
1297→      free(srvs->hostlist_str);
1298→      memset(srvs, 0, sizeof(*srvs));
1299→      srvs->ntp_servers = argv[1];
1300→
1301→      memset(samples, 0, sizeof(*samples) *
1302→                         CONFIG_NETUTILS_NTPCLIENT_NUM_SAMPLES);
1303→
1304→      clock_gettime(CLOCK_REALTIME, &start_realtime);
1305→      clock_gettime(CLOCK_MONOTONIC, &start_monotonic);
1306→
1307→      nsamples = 0;
1308→      if (netlib_check_ipconnectivity(NULL, 1, 1) > 0)
1309→        {
1310→          /* Collect samples. */
1311→
1312→          for (i = 0; i < CONFIG_NETUTILS_NTPCLIENT_NUM_SAMPLES; i++)
1313→            {
1314→              /* Get next sample. */
1315→
1316→              ret = ntpc_get_ntp_sample(srvs, samples, nsamples);
1317→              if (ret < 0)
1318→                {
1319→                  errval = errno;
1320→                }
1321→              else
1322→                {
1323→                  ++nsamples;
1324→                }
1325→            }
1326→        }
1327→
1328→      /* Analyse samples. */
1329→
1330→      if (nsamples > 0)
1331→        {
1332→          int64_t offset;
1333→
1334→          /* Select median offset of samples. */
1335→
1336→          qsort(samples, nsamples, sizeof(*samples), sample_cmp);
1337→
1338→          for (i = 0; i < nsamples; i++)
1339→            {
1340→              ninfo("NTP sample[%d]: offset: %s%lu.%03lu sec, "
1341→                    "round-trip delay: %s%lu.%03lu sec\n",
1342→                    i,
1343→                    samples[i].offset < 0 ? "-" : "",
1344→                    (unsigned long)ntp_secpart(int64abs(samples[i].offset)),
1345→                    ntp_nsecpart(int64abs(samples[i].offset))
1346→                      / NSEC_PER_MSEC,
1347→                    samples[i].delay < 0 ? "-" : "",
1348→                    (unsigned long)ntp_secpart(int64abs(samples[i].delay)),
1349→                    ntp_nsecpart(int64abs(samples[i].delay))
1350→                      / NSEC_PER_MSEC);
1351→            }
1352→
1353→          if ((nsamples % 2) == 1)
1354→            {
1355→              offset = samples[nsamples / 2].offset;
1356→            }
1357→          else
1358→            {
1359→              int64_t offset1 = samples[nsamples / 2].offset;
1360→              int64_t offset2 = samples[nsamples / 2 - 1].offset;
1361→
1362→              /* Average of two middle offsets. */
1363→
1364→              if (offset1 > 0 && offset2 > 0)
1365→                {
1366→                  offset = ((uint64_t)offset1 + (uint64_t)offset2) / 2;
1367→                }
1368→              else if (offset1 < 0 && offset2 < 0)
1369→                {
1370→                  offset1 = -offset1;
1371→                  offset2 = -offset2;
1372→
1373→                  offset = ((uint64_t)offset1 + (uint64_t)offset2) / 2;
1374→
1375→                  offset = -offset;
1376→                }
1377→              else
1378→                {
1379→                  offset = (offset1 + offset2) / 2;
1380→                }
1381→            }
1382→
1383→          /* Adjust system time. */
1384→
1385→          ntpc_settime(offset, &start_realtime, &start_monotonic);
1386→
1387→          /* Save samples for ntpc_status() */
1388→
1389→          sem_wait(&g_ntpc_daemon.lock);
1390→          g_last_nsamples = nsamples;
1391→          memcpy(&g_last_samples, samples, nsamples * sizeof(*samples));
1392→          sem_post(&g_ntpc_daemon.lock);
1393→
1394→#ifndef CONFIG_NETUTILS_NTPCLIENT_STAY_ON
1395→          /* Configured to exit at success. */
1396→
1397→          exitcode = EXIT_SUCCESS;
1398→          break;
1399→
1400→#else
1401→
1402→          /* A full implementation of an NTP client would require much
1403→           * more.  I think we can skip most of that here.
1404→           */
1405→
1406→          if (g_ntpc_daemon.state == NTP_RUNNING)
1407→            {
1408→              ninfo("Waiting for %d seconds\n",
1409→                    CONFIG_NETUTILS_NTPCLIENT_POLLDELAYSEC);
1410→
1411→              sleep(CONFIG_NETUTILS_NTPCLIENT_POLLDELAYSEC);
1412→              retries = 0;
1413→              retry_delay = 1;
1414→            }
1415→
1416→          continue;
1417→#endif
1418→        }
1419→
1420→      /* Exceeded maximum retries? */
1421→
1422→      if (retries++ >= CONFIG_NETUTILS_NTPCLIENT_RETRIES)
1423→        {
1424→          nerr("ERROR: too many retries: %d\n", retries - 1);
1425→          exitcode = EXIT_FAILURE;
1426→          break;
1427→        }
1428→
1429→      /* Is this error a signal? If not, sleep before retry. */
1430→
1431→      if (errval != EINTR)
1432→        {
1433→          ninfo("Retry %d in %d seconds...\n", retries, retry_delay);
1434→          sleep(retry_delay);
1435→
1436→          retry_delay *= 2;
1437→          if (retry_delay > MAX_RETRY_INTERVAL)
1438→            {
1439→              retry_delay = MAX_RETRY_INTERVAL;
1440→            }
1441→        }
1442→
1443→      /* Keep retrying. */
1444→    }
1445→
1446→  /* The NTP client is terminating */
1447→
1448→  sched_unlock();
1449→
1450→  g_ntpc_daemon.state = NTP_STOPPED;
1451→  sem_post(&g_ntpc_daemon.sync);
1452→  free(srvs->hostlist_str);
1453→  free(srvs);
1454→  free(samples);
1455→  return exitcode;
1456→}
