1477→/****************************************************************************
1478→ * Name: ntpc_start_with_list
1479→ *
1480→ * Description:
1481→ *   Start the NTP daemon
1482→ *
1483→ * Returned Value:
1484→ *   On success, the non-negative task ID of the NTPC daemon is returned;
1485→ *   On failure, a negated errno value is returned.
1486→ *
1487→ ****************************************************************************/
1488→
1489→int ntpc_start_with_list(FAR const char *ntp_server_list)
1490→{
1491→  FAR char *task_argv[] =
1492→    {
1493→      (FAR char *)ntp_server_list,
1494→      NULL
1495→    };
1496→
1497→  /* Is the NTP in a non-running state? */
1498→
1499→  sem_wait(&g_ntpc_daemon.lock);
1500→  if (g_ntpc_daemon.state == NTP_NOT_RUNNING ||
1501→      g_ntpc_daemon.state == NTP_STOPPED)
1502→    {
1503→      /* Start the NTP daemon */
1504→
1505→      g_ntpc_daemon.state = NTP_STARTED;
1506→      g_ntpc_daemon.pid =
1507→        task_create("NTP daemon", CONFIG_NETUTILS_NTPCLIENT_SERVERPRIO,
1508→                    CONFIG_NETUTILS_NTPCLIENT_STACKSIZE, ntpc_daemon,
1509→                    task_argv);
1510→
1511→      /* Handle failures to start the NTP daemon */
1512→
1513→      if (g_ntpc_daemon.pid < 0)
1514→        {
1515→          int errval = errno;
1516→          DEBUGASSERT(errval > 0);
1517→
1518→          g_ntpc_daemon.state = NTP_STOPPED;
1519→          nerr("ERROR: Failed to start the NTP daemon: %d\n", errval);
1520→          sem_post(&g_ntpc_daemon.lock);
1521→          return -errval;
1522→        }
1523→
1524→      /* Wait for any daemon state change */
1525→
1526→      do
1527→        {
1528→          sem_wait(&g_ntpc_daemon.sync);
1529→        }
1530→      while (g_ntpc_daemon.state == NTP_STARTED);
1531→    }
1532→
1533→  sem_post(&g_ntpc_daemon.lock);
1534→  return g_ntpc_daemon.pid;
1535→}
