121→int dm_vol_set_mute(int on)
122→{
123→  s_mute = on ? 1 : 0;
124→  dm_vol_apply();
125→  vol_save();
126→  return s_mute;
127→}
128→
129→void dm_vol_apply(void)
130→{
131→  unsigned int reg;
132→  int r1, r2;
133→
134→  /* CONFIG_AUDIO_EXCLUDE_VOLUME=y strips the AUDIO_FU_VOLUME ioctl path,
135→     so drive DACL/R digital volume through aw-alsa-lib controls instead. */
136→
137→  reg = s_mute ? 0 : vol_percent_to_reg(s_vol);
138→  r1 = snd_ctl_set(CODEC_CARD, "DACL digital volume", reg);
139→  r2 = snd_ctl_set(CODEC_CARD, "DACR digital volume", reg);
140→  syslog(LOG_INFO, "[dm-vol] dac vol reg=%u (dACL=%d dACR=%d)\n", reg, r1, r2);
141→
142→  /* also keep TTS helper in sync (percent, 0 when mute) */
143→  dm_voice_set_speaker_volume(s_mute ? 0 : s_vol);
144→}
145→
146→int dm_vol_set(int percent)
147→{
148→  if (percent < 0)
149→    {
150→      percent = 0;
151→    }
152→  if (percent > 100)
153→    {
154→      percent = 100;
155→    }
156→  s_vol = percent;
157→  if (s_vol > 0)
158→    {
159→      s_mute = 0;
160→    }
161→  dm_vol_apply();
162→  vol_save();
163→  return s_vol;
164→}
