 35→static void *voice_preview_worker(void *arg)
 36→{
 37→  struct voice_preview_job_s *job = arg;
 38→  char text[sizeof(job->text)];
 39→
 40→  snprintf(text, sizeof(text), "%s", job->text);
 41→  free(job);
