{
  FILE *f;
  unsigned char *raw;
  char *b64;
  char *body;
  long sz;
  int n;
  char *p;
  char *q;

  text[0] = '\0';
  f = fopen(wav, "rb");
  if (!f)
    {
      return -1;
    }
  fseek(f, 0, SEEK_END);
  sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (sz <= 44 || sz > 2 * 1024 * 1024)
    {
      fclose(f);
      return -1;
    }
  raw = malloc((size_t)sz);
  b64 = malloc((size_t)sz * 2 + 8);
  body = malloc((size_t)sz * 2 + 256);
  if (!raw || !b64 || !body)
    {
      free(raw); free(b64); free(body); fclose(f);
      return -1;
    }
  if (fread(raw, 1, (size_t)sz, f) != (size_t)sz)
    {
      free(raw); free(b64); free(body); fclose(f);
      return -1;
    }
  fclose(f);
  b64_encode(raw, (size_t)sz, b64, (size_t)sz * 2 + 8);
  free(raw);

  /* chat/completions ASR: input_audio */
  n = snprintf(body, (size_t)sz * 2 + 256,
               "{\"model\":\"%s\",\"messages\":[{\"role\":\"user\",\"content\":"
               "[{\"type\":\"input_audio\",\"input_audio\":{\"data\":\"%s\","
               "\"format\":\"wav\"}}]}]}",
               ASR_MODEL, b64);
  free(b64);
  if (n <= 0)
    {
      free(body);
      return -1;
    }
  if (http_post_json("/chat/completions", body, TXT_ASR) != 0)
    {
      free(body);
      return -1;
    }
  free(body);

  f = fopen(TXT_ASR, "rb");
  if (!f)
    {
      return -1;
    }
  fseek(f, 0, SEEK_END);
  sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (sz <= 0 || sz > 256 * 1024)
    {
      fclose(f);
      return -1;
    }
  body = malloc((size_t)sz + 1);
  if (!body)
    {
      fclose(f);
      return -1;
    }
  if (fread(body, 1, (size_t)sz, f) != (size_t)sz)
    {
      free(body);
      fclose(f);
      return -1;
    }
  body[sz] = '\0';
  fclose(f);

  p = strstr(body, "\"content\"");
  if (p)
    {
      p = strchr(p + 9, '"');
      if (p)
        {
          q = strchr(p + 1, '"');
          if (q)
            {
              size_t ln = (size_t)(q - p - 1);
              if (ln >= (size_t)cap)
                {
                  ln = (size_t)cap - 1;
                }
              memcpy(text, p + 1, ln);
              text[ln] = '\0';
            }
        }
    }
  free(body);
  return text[0] ? 0 : -1;
}

